/**
 * ReportGenerator - Produces a summary report for a container of nodes.
 * Returns a formatted text report with status overview.
 */

local container = $node;
local report = CreateArray();

local total = 0;
local up = 0;
local down = 0;
local unknown = 0;

foreach (child : GetChildObjects(container))
{
  if (child.class != 'Node') continue;
  total++;
  if (child.status == 0) up++;
  else if (child.status >= 4) down++;
  else unknown++;
}

report->append('=== Status Report: ' + container.name + ' ===');
report->append('Generated: ' + FormatDate(time(), '%Y-%m-%d %H:%M:%S UTC'));
report->append('');
report->append('Total nodes:   ' + total);
report->append('Normal:        ' + up);
report->append('Problem:       ' + (total - up - unknown));
report->append('Unknown:       ' + unknown);
report->append('Down/Critical: ' + down);
report->append('');

local pct = (total > 0) ? (up * 100 / total) : 0;
report->append('Availability:  ' + pct + '%');

return ArrayToString(report, '\n');
